import { B, DIRS, roof } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

// ---- palette (palette.json ids only) ------------------------------------------------------------------------------
export const STONE_BRICKS = "stone_bricks", ANDESITE = "andesite", COBBLESTONE = "cobblestone";
