  [20, 9, 25, 13, "foyer"], [20, 14, 25, 15, "foyer"], [13, 9, 18, 14, "office"], [27, 9, 32, 14, "dining"],
  [30, 5, 32, 7, "bay"], [20, 16, 32, 22, "kitchen"], [34, 13, 42, 26, "family"], [13, 16, 18, 22, "mudroom"],
  [1, 7, 11, 18, "garage"],
