  const r = inRoom(S1_ROOMS, x, z);
  if (!r) return [SMOOTH_STONE, {}];
  const [x0, z0, x1, z1, kind] = r;
  if (kind === "foyer") return [checker(x, z, POLISHED_ANDESITE, SMOOTH_QUARTZ), {}];
